import{decodeResults}from"./ctc.js";import{MIN_CROP_WIDTH}from"./ctc.js";import{preprocessImage}from"./image-tensor.js";import{recognizeCropsBatched}from"./batched.js";import{groupBoxesIntoLines,mergeLineCrop,packIntoBatches,splitTextByPositions}from"./line-grouping.js";export function rotateTallCropIfNeeded(crop,ctx){if(!(ctx.options.rotateVerticalCrops??true))return crop;if(crop.height/crop.width<1.5)return crop;let rotated=ctx.platform.createCanvas(crop.height,crop.width);let c=rotated.getContext("2d");c.translate(0,crop.width);c.rotate(-Math.PI/2);c.drawImage(crop,0,0);return rotated}export function cropRegion(sourceCanvas,box,canvasOps){return canvasOps.getToolkit().crop({bbox:{x0:box.x,y0:box.y,x1:box.x+box.width,y1:box.y+box.height},canvas:sourceCanvas})}async function recognizeText(cropCanvas,ctx,charactersDictionary){let targetHeight=ctx.options.imageHeight??48;let imageProcessor=ctx.engine==="opencv"?ctx.platform.imageProcessor:undefined;const{imageTensor,tensorWidth,tensorHeight}=await preprocessImage(cropCanvas,targetHeight,imageProcessor,ctx.platform.canvas.createProcessor.bind(ctx.platform.canvas));let inputTensor;try{inputTensor=new ctx.platform.ort.Tensor("float32",imageTensor,[1,3,tensorHeight,tensorWidth]);let result=await ctx.runInference(inputTensor);let dict=charactersDictionary??ctx.options.charactersDictionary??[];return decodeResults(result,dict,tensorWidth,ctx.debugging.verbose)}finally{inputTensor?.dispose()}}function sortByReadingOrder(results){return[...results].sort((a,b)=>{if(Math.abs(a.box.y-b.box.y)<(a.box.height+b.box.height)/4){return a.box.x-b.box.x}return a.box.y-b.box.y})}export async function runPerBoxStrategy(sourceCanvas,validBoxes,ctx,processBox,charactersDictionary){let cropsDebugPath=ctx.debugging.debugFolder?`${ctx.debugging.debugFolder}${ctx.platform.pathSeparator}crops`:"";if(ctx.debugging.debug&&cropsDebugPath){let toolkit=ctx.platform.canvas.getToolkit();if("clearOutput"in toolkit&&typeof toolkit.clearOutput==="function"){toolkit.clearOutput(cropsDebugPath)}}if(!ctx.debugging.debug){let crops=validBoxes.map(({box})=>rotateTallCropIfNeeded(cropRegion(sourceCanvas,box,ctx.platform.canvas),ctx));let recognized=await recognizeCropsBatched(crops,ctx,charactersDictionary);let results=validBoxes.map(({box},i)=>({text:recognized[i]?.text??"",box,confidence:recognized[i]?.confidence??0}));return sortByReadingOrder(results)}let results=[];for(const{box,index}of validBoxes){let result=await processBox(sourceCanvas,box,index,validBoxes.length,cropsDebugPath,charactersDictionary);if(result!==null){results.push(result)}}return sortByReadingOrder(results)}export async function runLineStrategy(sourceCanvas,validBoxes,ctx,charactersDictionary){let lines=groupBoxesIntoLines(validBoxes);let jobs=[];let crops=[];for(let lineBoxes of lines){let first=lineBoxes[0];if(!first)continue;if(lineBoxes.length===1){crops.push(rotateTallCropIfNeeded(cropRegion(sourceCanvas,first.box,ctx.platform.canvas),ctx));jobs.push({lineBoxes,cropWidths:null})}else{const{mergedCanvas,cropWidths}=mergeLineCrop(sourceCanvas,lineBoxes,ctx.platform.createCanvas.bind(ctx.platform),ctx.platform.canvas);crops.push(mergedCanvas);jobs.push({lineBoxes,cropWidths})}}let recognized=await recognizeCropsBatched(crops,ctx,charactersDictionary);let results=[];jobs.forEach((job,i)=>{let rec=recognized[i];if(!rec)return;if(job.cropWidths===null){let first=job.lineBoxes[0];if(first)results.push({text:rec.text,box:first.box,confidence:rec.confidence})}else{let pieces=splitTextByPositions(rec.text,rec.positions,job.cropWidths);for(let i2=0;i2<job.lineBoxes.length;i2++){let lb=job.lineBoxes[i2];if(!lb)continue;results.push({text:(pieces[i2]??"").trim(),box:lb.box,confidence:rec.confidence})}}});return sortByReadingOrder(results)}export async function runCrossLineStrategy(sourceCanvas,validBoxes,ctx,charactersDictionary){let lines=groupBoxesIntoLines(validBoxes);let targetHeight=ctx.options.imageHeight??48;let SEPARATOR_GAP=20;let lineCrops=[];for(let lineBoxes of lines){if(lineBoxes.length===1){let first=lineBoxes[0];if(!first)continue;let canvas=cropRegion(sourceCanvas,first.box,ctx.platform.canvas);lineCrops.push({canvas,boxes:lineBoxes,cropWidths:[canvas.width]})}else{const{mergedCanvas,cropWidths}=mergeLineCrop(sourceCanvas,lineBoxes,ctx.platform.createCanvas.bind(ctx.platform),ctx.platform.canvas);lineCrops.push({canvas:mergedCanvas,boxes:lineBoxes,cropWidths})}}let resized=lineCrops.map(({canvas,boxes,cropWidths},i)=>{let ar=canvas.width/canvas.height;let resizedWidth=Math.max(MIN_CROP_WIDTH,Math.round(targetHeight*ar));return{canvas,boxes,cropWidths,resizedWidth,originalHeight:canvas.height,index:i}});let maxWidth=Math.max(...resized.map((r)=>r.resizedWidth));let widthFactor=ctx.options.crossLineWidthFactor??1.5;let batchTargetWidth=Math.round(maxWidth*widthFactor);let batches=packIntoBatches(resized,(item)=>item.resizedWidth,batchTargetWidth,SEPARATOR_GAP);let results=[];for(let batch of batches){let batchSorted=[...batch].sort((a,b)=>a.index-b.index);let maxOriginalHeight=Math.max(...batchSorted.map((item)=>item.originalHeight));let stretchedWidths=batchSorted.map((item)=>{if(item.originalHeight>=maxOriginalHeight)return item.resizedWidth;let heightScale=maxOriginalHeight/item.originalHeight;return Math.max(MIN_CROP_WIDTH,Math.round(item.resizedWidth*heightScale))});let totalCropWidth=stretchedWidths.reduce((sum,w)=>sum+w,0);let totalWidth=totalCropWidth+SEPARATOR_GAP*(batchSorted.length-1);let batchCanvas=ctx.platform.createCanvas(totalWidth,targetHeight);let bctx=batchCanvas.getContext("2d");bctx.fillStyle="white";bctx.fillRect(0,0,totalWidth,targetHeight);let offsetX=0;for(let i=0;i<batchSorted.length;i++){let item=batchSorted[i];let drawWidth=stretchedWidths[i];if(item===undefined||drawWidth===undefined)continue;bctx.drawImage(item.canvas,0,0,item.canvas.width,item.canvas.height,offsetX,0,drawWidth,targetHeight);offsetX+=drawWidth;if(i<batchSorted.length-1)offsetX+=SEPARATOR_GAP}const{text:batchText,confidence:batchConf,positions}=await recognizeText(batchCanvas,ctx,charactersDictionary);let flatSegments=[];let flatBoxes=[];for(let i=0;i<batchSorted.length;i++){let item=batchSorted[i];let drawWidth=stretchedWidths[i];if(!item||drawWidth===undefined)continue;let scale=drawWidth/item.canvas.width;for(let j=0;j<item.boxes.length;j++){let lb=item.boxes[j];if(!lb)continue;let w=(item.cropWidths[j]??0)*scale;if(j===item.boxes.length-1&&i<batchSorted.length-1)w+=SEPARATOR_GAP;flatSegments.push(w);flatBoxes.push(lb)}}let pieces=splitTextByPositions(batchText,positions,flatSegments);for(let k=0;k<flatBoxes.length;k++){let lb=flatBoxes[k];if(!lb)continue;results.push({text:(pieces[k]??"").trim(),box:lb.box,confidence:batchConf})}}return sortByReadingOrder(results)}